/* ChartPulse Global Styles */
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16162a;
  --bg-card: #1e1e32;
  --bg-hover: #252540;
  --border-color: #2a2a45;
  --text-primary: #e8e8f0;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e4fd8;
  --accent-green: #22c55e;
  --accent-red: #F7525F;
  --accent-yellow: #f59e0b;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: var(--bg-secondary);
}
::-webkit-scrollbar-thumb {
  background: #3a3a5c;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #4a4a6c;
}

/* Utility Classes */
.text-green { color: var(--accent-green); }
.text-red { color: var(--accent-red); }
.text-blue { color: var(--accent-blue); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }

.bg-card { background: var(--bg-card); }
.bg-secondary { background: var(--bg-secondary); }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }

.p-3 { padding: 0.75rem; }
.p-4 { padding: 1rem; }
.p-6 { padding: 1.5rem; }

.rounded { border-radius: 0.5rem; }
.rounded-lg { border-radius: 0.75rem; }

.border { border: 1px solid var(--border-color); }

.w-full { width: 100%; }
.h-full { height: 100%; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  border: none;
  transition: all 0.15s ease;
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}
.btn-primary:hover {
  background: var(--accent-blue-hover);
  text-decoration: none;
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-outline:hover {
  background: var(--bg-hover);
  text-decoration: none;
}

.btn-sm {
  padding: 0.375rem 0.75rem;
  font-size: 0.75rem;
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.125rem 0.5rem;
  border-radius: 0.25rem;
  font-size: 0.75rem;
  font-weight: 600;
}

.badge-green {
  background: rgba(34, 197, 94, 0.15);
  color: var(--accent-green);
}

.badge-red {
  background: rgba(247, 82, 95, 0.15);
  color: var(--accent-red);
}

.badge-blue {
  background: rgba(41, 98, 255, 0.15);
  color: var(--accent-blue);
}

.badge-gold {
  background: rgba(245, 158, 11, 0.15);
  color: var(--accent-yellow);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  background: var(--bg-tertiary);
  padding: 0.25rem;
  border-radius: 0.5rem;
  width: fit-content;
}

.tab-btn {
  padding: 0.5rem 1rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--text-primary);
}

.tab-btn.active {
  background: var(--bg-card);
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.data-table th {
  text-align: left;
  padding: 0.625rem 1rem;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.025em;
  border-bottom: 1px solid var(--border-color);
}

.data-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
}

.data-table tr:hover td {
  background: var(--bg-hover);
}

.data-table tr:last-child td {
  border-bottom: none;
}

/* Sparkline */
.sparkline {
  width: 80px;
  height: 28px;
}

/* Card */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  overflow: hidden;
}

.card-header {
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
}

.card-body {
  padding: 1rem 1.25rem;
}

/* Navbar */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 1.5rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}

.navbar-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--text-primary);
}

.navbar-brand:hover {
  text-decoration: none;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-link {
  padding: 0.5rem 0.875rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 0.15s ease;
}

.nav-link:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
  text-decoration: none;
}

.nav-link.active {
  color: var(--accent-blue);
  background: rgba(41, 98, 255, 0.1);
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 3rem 1.5rem 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--text-primary);
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: var(--text-secondary);
  padding: 0.25rem 0;
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  max-width: 1200px;
  margin: 2rem auto 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Section */
.section {
  padding: 2rem 1.5rem;
  max-width: 1280px;
  margin: 0 auto;
}

.section-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

/* Grid */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .navbar { padding: 0 1rem; }
  .nav-links { display: none; }
  .section { padding: 1.5rem 1rem; }
  .footer-bottom { flex-direction: column; gap: 0.5rem; text-align: center; }
}

/* Mobile nav toggle */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.25rem;
  cursor: pointer;
}

@media (max-width: 768px) {
  .mobile-menu-btn { display: block; }
}

/* Watchlist accordion */
.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 0.875rem;
  background: var(--bg-tertiary);
  cursor: pointer;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
}

.accordion-header:hover {
  background: var(--bg-hover);
}

.accordion-icon {
  transition: transform 0.2s ease;
  font-size: 0.625rem;
}

.accordion-header.collapsed .accordion-icon {
  transform: rotate(-90deg);
}

.accordion-body {
  overflow: hidden;
  transition: max-height 0.2s ease;
}

.accordion-body.collapsed {
  max-height: 0;
}

/* Watchlist row */
.watchlist-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 0.5rem;
  padding: 0.5rem 0.875rem;
  font-size: 0.8125rem;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  align-items: center;
}

.watchlist-row:hover {
  background: var(--bg-hover);
}

.watchlist-row .symbol {
  font-weight: 600;
  color: var(--text-primary);
}

.watchlist-row .last {
  color: var(--text-primary);
  text-align: right;
}

.watchlist-row .chg {
  text-align: right;
}

.watchlist-row .chg-pct {
  text-align: right;
  font-weight: 500;
}

/* Chart toolbar */
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}

.toolbar-btn {
  padding: 0.375rem 0.625rem;
  border-radius: 0.25rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}

.toolbar-btn:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.toolbar-btn.active {
  background: var(--accent-blue);
  color: white;
}

.toolbar-sep {
  width: 1px;
  height: 20px;
  background: var(--border-color);
  margin: 0 0.25rem;
}

/* Idea card */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  overflow: hidden;
  transition: border-color 0.15s ease;
}

.idea-card:hover {
  border-color: #3a3a5c;
}

.idea-card-header {
  padding: 1rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.875rem;
  color: white;
  flex-shrink: 0;
}

.idea-meta {
  flex: 1;
  min-width: 0;
}

.idea-author {
  font-weight: 600;
  font-size: 0.875rem;
}

.idea-time {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.idea-card-body {
  padding: 0 1rem 1rem;
}

.idea-title {
  font-weight: 600;
  font-size: 0.9375rem;
  margin-bottom: 0.5rem;
}

.idea-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.idea-card-footer {
  padding: 0.75rem 1rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.idea-stats {
  display: flex;
  gap: 1rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Broker card */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  transition: border-color 0.15s ease;
}

.broker-card:hover {
  border-color: #3a3a5c;
}

.broker-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.broker-name {
  font-weight: 700;
  font-size: 1.0625rem;
}

.broker-rating {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-top: 0.25rem;
}

.broker-rating-score {
  font-weight: 700;
  font-size: 1rem;
  color: var(--accent-yellow);
}

.broker-rating-text {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.broker-stats {
  display: flex;
  gap: 1.5rem;
}

.broker-stat {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.broker-stat-value {
  font-weight: 600;
  font-size: 0.9375rem;
}

.broker-stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.broker-promo {
  font-size: 0.8125rem;
  color: var(--accent-green);
  background: rgba(34, 197, 94, 0.08);
  padding: 0.5rem 0.75rem;
  border-radius: 0.375rem;
}

/* Stats banner */
.stats-banner {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  padding: 2rem;
  display: flex;
  justify-content: space-around;
  text-align: center;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.stats-banner-item {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.stats-banner-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent-blue);
}

.stats-banner-label {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Market summary bar */
.market-bar {
  display: flex;
  gap: 1.5rem;
  overflow-x: auto;
  padding: 0.75rem 1.5rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}

.market-bar-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
  font-size: 0.8125rem;
}

.market-bar-name {
  color: var(--text-secondary);
}

.market-bar-price {
  font-weight: 600;
  color: var(--text-primary);
}

.market-bar-change {
  font-weight: 500;
}

/* News card */
.news-card {
  display: flex;
  gap: 1rem;
  padding: 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  transition: border-color 0.15s ease;
}

.news-card:hover {
  border-color: #3a3a5c;
}

.news-thumb {
  width: 80px;
  height: 60px;
  background: var(--bg-tertiary);
  border-radius: 0.375rem;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.news-content {
  flex: 1;
  min-width: 0;
}

.news-title {
  font-weight: 600;
  font-size: 0.9375rem;
  margin-bottom: 0.25rem;
  line-height: 1.4;
}

.news-meta {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Stock detail panel */
.detail-panel {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  padding: 1.25rem;
}

.detail-header {
  margin-bottom: 1rem;
}

.detail-ticker {
  font-size: 1.5rem;
  font-weight: 700;
}

.detail-company {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.detail-price {
  font-size: 2rem;
  font-weight: 700;
  margin: 0.5rem 0;
}

.detail-change {
  display: flex;
  gap: 0.75rem;
  font-size: 0.9375rem;
  font-weight: 500;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  margin-top: 1rem;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.detail-item-label {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.detail-item-value {
  font-size: 0.875rem;
  font-weight: 500;
}

/* Financials table compact */
.fin-table {
  width: 100%;
  font-size: 0.8125rem;
  border-collapse: collapse;
}

.fin-table th,
.fin-table td {
  padding: 0.5rem 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

.fin-table th {
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.75rem;
}

/* Mini chart canvas container */
.mini-chart-wrap {
  position: relative;
  width: 100%;
  height: 200px;
  background: var(--bg-card);
  border-radius: 0.5rem;
  overflow: hidden;
}

/* Hero */
.hero {
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  padding: 4rem 1.5rem;
  text-align: center;
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 2rem;
  line-height: 1.6;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* Pagination */
.pagination {
  display: flex;
  gap: 0.25rem;
  justify-content: center;
  margin-top: 1.5rem;
}

.page-btn {
  padding: 0.5rem 0.875rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: all 0.15s ease;
}

.page-btn:hover {
  background: var(--bg-hover);
}

.page-btn.active {
  background: var(--accent-blue);
  color: white;
  border-color: var(--accent-blue);
}

/* Toggle switch */
.toggle-switch {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
  cursor: pointer;
}

.toggle-switch input {
  appearance: none;
  width: 36px;
  height: 20px;
  background: var(--bg-hover);
  border-radius: 10px;
  position: relative;
  cursor: pointer;
  outline: none;
  transition: background 0.15s ease;
}

.toggle-switch input::after {
  content: '';
  position: absolute;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  top: 2px;
  left: 2px;
  transition: transform 0.15s ease;
}

.toggle-switch input:checked {
  background: var(--accent-blue);
}

.toggle-switch input:checked::after {
  transform: translateX(16px);
}

/* Gainers/Losers list */
.mover-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 0;
  border-bottom: 1px solid var(--border-color);
  font-size: 0.875rem;
}

.mover-row:last-child {
  border-bottom: none;
}

.mover-name {
  font-weight: 500;
}

.mover-change {
  font-weight: 600;
}

/* Yield curve bar */
.yield-bar {
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
  height: 120px;
  padding: 1rem;
  background: var(--bg-card);
  border-radius: 0.5rem;
}

.yield-bar-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.375rem;
}

.yield-bar-fill {
  width: 100%;
  background: var(--accent-blue);
  border-radius: 0.25rem 0.25rem 0 0;
  min-height: 4px;
  transition: height 0.3s ease;
}

.yield-bar-label {
  font-size: 0.625rem;
  color: var(--text-muted);
}

.yield-bar-value {
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* Earnings row */
.earnings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border-color);
  font-size: 0.875rem;
}

