        const tf = btn.dataset.timeframe;
        let count = 60, vol = 3;
        if (tf === '1D') { count = 24; vol = 1; }
        else if (tf === '5D') { count = 50; vol = 2; }
        else if (tf === '1M') { count = 30; vol = 3; }
        else if (tf === '3M') { count = 60; vol = 4; }
